contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We test the general rule about donate(uint256) forwarding value to the whale:
    // If donate() call (with value 'donateAmount') does not revert, then the contract's balance
    // must have decreased by at least donateAmount. We observe this via address(c).balance before/after
    // and also check winnersPot non-increase as an additional observable consequence.
    function run(uint256 donateAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donateAmount)); require(donateAmount <= 1000000000000000000000000000000);
        // caller must fund this test contract so it can forward donateAmount
        require(address(this).balance >= donateAmount);

        // record balances before
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore = c.winnersPot(); if (__ESBMC_reverted()) return;

        // attempt donate with value donateAmount, capture whether it reverted
        bool donateReverted;
        c.donate{value: donateAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            donateReverted = true;
        } else {
            donateReverted = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter = c.winnersPot(); if (__ESBMC_reverted()) return;

        // General rule: if donate succeeded then the contract's balance must decrease by at least donateAmount
        // and winnersPot (balance/2) cannot increase. If donate reverted, no guarantee, so only require the implication.
        assert(donateReverted || (balanceAfter + donateAmount <= balanceBefore && winnersPotAfter <= winnersPotBefore));
    }

    // Allow receiving Ether so the harness can fund this contract
    receive() external payable {}
}

