// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 donateAmount) internal {
        donateAmount = bound(donateAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= donateAmount);
        uint256 balanceBefore = address(c).balance;
        uint256 winnersPotBefore;
        try c.winnersPot() returns (uint256 __r) { winnersPotBefore = __r; } catch { return; }
        bool donateReverted;
        try c.donate{value: donateAmount}() {
            donateReverted = false;
        } catch {
            donateReverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        uint256 winnersPotAfter;
        try c.winnersPot() returns (uint256 __r) { winnersPotAfter = __r; } catch { return; }
        assertTrue(donateReverted || (balanceAfter + donateAmount <= balanceBefore && winnersPotAfter <= winnersPotBefore));
    }

    function testFuzz_run(uint256 donateAmount) public {
        _run(donateAmount);
    }

    receive() external payable {}
}
